import glob, json, sys
from pathlib import Path
files = {Path(f).stem: Path(f) for f in glob.glob('/home/claude/FalePDF/network/tools/vorlagen/data/*/*.json')}
def E(jid, old, new):
    p = files[jid]; t = p.read_text(encoding='utf-8')
    n = t.count(old)
    if n != 1: print('!! ', jid, n, old[:60]); return
    p.write_text(t.replace(old, new), encoding='utf-8')
